const staticData = $getWorkflowStaticData('global');

const recipient = 'effect3.agency@gmail.com';
const sources = [
  {
    formType: 'onboarding',
    url: 'https://docs.google.com/spreadsheets/d/1ZVTEiXft3cigE9DqshrefMpwx7IgfsFu1nHBCoyhGvU/gviz/tq?tqx=out:csv&sheet=Onboarding'
  },
  {
    formType: 'careers',
    url: 'https://docs.google.com/spreadsheets/d/1ZVTEiXft3cigE9DqshrefMpwx7IgfsFu1nHBCoyhGvU/gviz/tq?tqx=out:csv&sheet=Careers'
  }
];

function parseCsv(text) {
  const rows = [];
  let row = [];
  let value = '';
  let inQuotes = false;

  for (let i = 0; i < text.length; i++) {
    const char = text[i];
    const next = text[i + 1];

    if (char === '"') {
      if (inQuotes && next === '"') {
        value += '"';
        i++;
      } else {
        inQuotes = !inQuotes;
      }
      continue;
    }

    if (char === ',' && !inQuotes) {
      row.push(value);
      value = '';
      continue;
    }

    if ((char === '\n' || char === '\r') && !inQuotes) {
      if (char === '\r' && next === '\n') i++;
      row.push(value);
      value = '';
      if (row.some(cell => String(cell).trim() !== '')) rows.push(row);
      row = [];
      continue;
    }

    value += char;
  }

  if (value.length > 0 || row.length > 0) {
    row.push(value);
    if (row.some(cell => String(cell).trim() !== '')) rows.push(row);
  }

  return rows;
}

function rowToObject(headers, row) {
  const obj = {};
  headers.forEach((header, index) => {
    obj[header] = row[index] ?? '';
  });
  return obj;
}

const seenKeys = new Set(Array.isArray(staticData.seenKeys) ? staticData.seenKeys : []);
const initialized = Boolean(staticData.initialized);
const newItems = [];

for (const source of sources) {
  const response = await fetch(source.url);
  if (!response.ok) {
    throw new Error(`Failed to fetch ${source.formType} sheet: ${response.status}`);
  }

  const csv = await response.text();
  const rows = parseCsv(csv);
  if (rows.length < 2) continue;

  const headers = rows[0];
  const entries = rows.slice(1).filter(row => row.some(cell => String(cell).trim() !== ''));

  for (const row of entries) {
    const entry = rowToObject(headers, row);
    const key = `${source.formType}:${entry.submittedAt || ''}:${entry.email || ''}:${entry.name || ''}`;

    if (!initialized) {
      seenKeys.add(key);
      continue;
    }

    if (seenKeys.has(key)) continue;
    seenKeys.add(key);

    if (source.formType === 'onboarding') {
      newItems.push({
        json: {
          recipient,
          formType: source.formType,
          submittedAt: entry.submittedAt || '',
          subject: `New Effect3 onboarding entry — ${entry.name || entry.brandName || 'Unknown'}`,
          message: `New onboarding entry received on Effect3.\n\nSubmitted at: ${entry.submittedAt || 'Unknown'}\nName: ${entry.name || 'Unknown'}\nEmail: ${entry.email || 'Unknown'}\nPhone: ${entry.phone || 'Not provided'}\nBrand: ${entry.brandName || 'Not provided'}\nCategory: ${entry.category || 'Not provided'}\nWebsite: ${entry.website || 'Not provided'}\nMode: ${entry.mode || 'Not provided'}\nProblem: ${entry.problem || 'Not provided'}\nAgents: ${entry.agents || 'Not provided'}\n\nSheet: Onboarding\nSource: https://docs.google.com/spreadsheets/d/1ZVTEiXft3cigE9DqshrefMpwx7IgfsFu1nHBCoyhGvU/edit`
        }
      });
    } else {
      newItems.push({
        json: {
          recipient,
          formType: source.formType,
          submittedAt: entry.submittedAt || '',
          subject: `New Effect3 careers entry — ${entry.name || 'Unknown'}`,
          message: `New careers application received on Effect3.\n\nSubmitted at: ${entry.submittedAt || 'Unknown'}\nName: ${entry.name || 'Unknown'}\nEmail: ${entry.email || 'Unknown'}\nRole: ${entry.role || 'Not provided'}\nMessage: ${entry.message || 'Not provided'}\nSource: ${entry.source || 'Not provided'}\n\nSheet: Careers\nSource: https://docs.google.com/spreadsheets/d/1ZVTEiXft3cigE9DqshrefMpwx7IgfsFu1nHBCoyhGvU/edit`
        }
      });
    }
  }
}

staticData.initialized = true;
staticData.seenKeys = Array.from(seenKeys).slice(-500);

return newItems;
